mapper.select:
select * from ( SELECT t.*, (st_distance(point(t.tearoom_longitude, t.tearoom_latitude), point(#{longitude}, #{latitude})) * 111195) AS distance, u.user_name AS userName, u.phone, IFNULL(( SELECT CASE WHEN ( SELECT IFNULL(uv.is_vip, 0) FROM user_vip uv WHERE uv.user_id = #{byUserId} AND uv.is_vip = 1 AND NOW() BETWEEN uv.create_time AND uv.end_time ) = 1 THEN gt.member_electricity_price ELSE gt.electricity_price END FROM goods_time gt WHERE gt.tearoom_id = t.tearoom_id AND DATE_FORMAT(NOW(), '%H:%i:%s') BETWEEN gt.start_time AND gt.end_time LIMIT 1 ), 0) AS price, (SELECT COUNT(*) FROM goods g WHERE g.goods_category=1 AND g.tearoom_id=t.tearoom_id) AS kuaiCount, (SELECT COUNT(*) FROM goods g WHERE g.goods_category=1 AND g.tearoom_id=t.tearoom_id AND g.goods_status=2) AS kuaiCount2, (SELECT COUNT(*) FROM goods g WHERE g.goods_category=2 AND g.tearoom_id=t.tearoom_id) AS manCount, (SELECT COUNT(*) FROM goods g WHERE g.goods_category=2 AND g.tearoom_id=t.tearoom_id AND g.goods_status=2) AS manCount2 FROM tearoom t LEFT JOIN tb_user u ON u.user_id = t.user_id WHERE 1=1
and t.tearoom_city like concat('%',#{city},'%')
and t.status = #{status}
and t.tearoom_name like concat('%',#{tearoomName},'%')
and t.user_id = #{userId}
and t.tearoom_type = #{tearoomType}
and u.user_name like concat('%',#{userName},'%')
and t.tearoom_phone like concat('%',#{tearoomPhone},'%')
and (t.user_id = #{tearoomUserId} or t.employee_user_ids like concat('%,',#{tearoomUserId},'') or t.employee_user_ids like concat('',#{tearoomUserId},',%') or t.employee_user_ids like concat('%,',#{tearoomUserId},',%') or t.employee_user_ids = #{tearoomUserId} )
and t.shop_type = #{shopType}
and t.is_vip_privilege = #{isVipPrivilege}
) a
order by distance asc,create_time desc
order by distance asc,create_time desc
where kuaiCount>0 order by distance asc
where manCount>0 order by distance asc
order by distance asc
order by price asc

select t.*,(st_distance(point(t.tearoom_longitude, t.tearoom_latitude), point(#{longitude}, #{latitude})) * 111195) as distance, u.user_name as userName,u.phone, (select count(*) from goods g where g.goods_category=1 and g.tearoom_id=t.tearoom_id) as kuaiCount, (select count(*) from goods g where g.goods_category=1 and g.tearoom_id=t.tearoom_id and g.goods_status=2) as kuaiCount2, (select count(*) from goods g where g.goods_category=2 and g.tearoom_id=t.tearoom_id) as manCount, (select count(*) from goods g where g.goods_category=2 and g.tearoom_id=t.tearoom_id and g.goods_status=2) as manCount2 from orders o left join tearoom t on t.tearoom_id=o.tearoom_id left join tb_user u on u.user_id=t.user_id where t.tearoom_id is not null and o.user_id=#{userId} and t.status=1
and tearoom_type=#{tearoomType}
group by o.tearoom_id order by o.create_time desc
